/* Original Grade 5 visual practice. Three bounded examples per challenge.
   These short activities support a school year; they are not a full course or
   a fluency certification. Models keep givens fixed while learners respond. */
const lesson = (suffix, title, topicId, unit, conceptKey, standards, goal, prerequisite, workedExample, explainPrompt, reviewPrompt) => ({
  id: `g5y-${suffix}`, title, topicId, unitId: `g5-unit-${unit}`, conceptKey, conceptId: conceptKey,
  bandId: 'elementary', gradeIds: ['5'], worldId: ['geometry', 'measurement', 'measuring', 'data', 'coordinates'].includes(topicId) ? 'studio' : topicId === 'fractions' ? 'garden' : 'workshop',
  standards, sourceIds: [], lessonId: null, minutes: 10, goal, skill: goal,
  teacherNotes: 'Build or mark an example together, explain the units, and revisit a different bounded example. Completion records practice, including supported practice.',
  lessonPlan: { goal, prerequisite, workedExample, explainPrompt, reviewPrompt }
});
